import requests
from requests.models import Request

class FileWrapper:
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=None: b'file content'
        if name == 'name':
            return 'testfile.txt'
        raise AttributeError(name)

def test_getattr_file_wrapper():
    files = {'file': FileWrapper()}
    # We want to see how _encode_files handles this.
    # We can use requests.Request and then prepare it.
    req = Request('POST', 'http://httpbin.org/post', files=files)
    prepared = req.prepare()

    # If it was detected as a file, the body should contain the content.
    # If it was NOT detected as a file, it might have been treated as a string
    # or something else, and the body might be different.

    print(f'Body: {prepared.body}')
    assert b'file content' in prepared.body
    print('Success!')

if __name__ == '__main__':
    try:
        test_getattr_file_wrapper()
    except Exception as e:
        print(f'Failure: {e}')
        import traceback
        traceback.print_exc()

